// System call ids for x86 ABIs
// Autogenerated by kernel-syscall-info

package syscallinfo

import (
	"runtime"
	"testing"

	"github.com/cilium/tetragon/pkg/syscallinfo"
	"github.com/stretchr/testify/require"
)

func TestIDs(t *testing.T) {
	if runtime.GOARCH != "amd64" {
		t.Skip()
	}
	for n, s := range kernelSyscallIDs {
		// remove "sys_" prefix
		name := n[4:]
		{
			id := int(-1)
			if s.X64 != nil {
				id = int(*s.X64)
			}
			ossid := syscallinfo.GetSyscallID(name)
			if ossid == -1 && ossid != id {
				t.Logf("oss syscallinfo seems to be missing for x64/%s", name)
				continue
			}
			require.Equal(t, ossid, id, name)
		}

		{
			id32 := int(-1)
			if s.IA32 != nil {
				id32 = int(*s.IA32)
			}
			ossid32 := syscallinfo.GetSyscallID32(name)
			if ossid32 == -1 && ossid32 != id32 {
				t.Logf("oss syscallinfo seems to be missing for ia32/%s", name)
				continue
			}
			if name == "oldstat" {
				// fixed in https://github.com/cilium/tetragon/pull/2550
				continue
			}
			require.Equal(t, ossid32, id32, name)
		}
	}
}
